SELECT 
FROM TB_CAPACITY_ACCOUNT


        AND ACCOUNT_NUMBER LIKE CONCAT('%', #{criteria.accountNumber}, '%')


        AND NAME LIKE CONCAT('%', #{criteria.name}, '%')


        AND ACCOUNT_TYPE = #{criteria.accountType}


        AND STATUS = #{criteria.status}


        AND CURRENCY = #{criteria.currency}


ORDER BY ACCOUNT_NUMBER

